function brandedHome(){return `<section class="church-home"><div class="church-home-copy"><span class="eyebrow">FOR THE WHOLE CHURCH. FOR EVERYDAY LIFE.</span><h1>Many people.<br>One body.<br><em>Life together.</em></h1><p>Connect the message on Sunday with the life of your church all week. Explore a shared direction for teaching, groups, families, leaders, and ministry.</p><div class="hero-actions">${link('explore','Explore the ministry library '+icon('arrow'),'primary')}${link('build','Shape our next season','button')}</div></div><div class="church-arches" role="img" aria-label="Layered architectural arches bringing many forms into one shared space"><div class="arch-one"></div><div class="arch-two"></div><div class="arch-three"></div><div class="arch-four"></div><div class="arch-five"></div><span>GATHER.<br>GROW.<br>GO.</span><small>A CHURCH FORMED THROUGH LIFE TOGETHER.</small></div></section><section class="church-common"><span class="eyebrow">A COMMON PURPOSE</span><h2>Every ministry belongs<br>in the bigger picture.</h2>${brandTopics([['Teaching','teaching'],['Discipleship','discipleship'],['Community','community'],['Leadership','leadership'],['Mission','mission']])}</section>${homeFinder('What is your church’s next faithful step?','BEGIN WITH THE PEOPLE YOU SERVE')}${homeShelf('Possibilities for the whole church.','EXPLORE YOUR NEXT SEASON')}${brandCTA('Let’s bring<br>it all together.','Name the vision. Connect the resources. Shape a shared journey your people can live.','Open the church studio')}`}

document.documentElement.style.setProperty('--accent',design.accent);document.documentElement.style.setProperty('--soft',design.soft);document.documentElement.style.setProperty('--ink',design.ink);
const stateKey=`lifetogether-network-${site.id}-v2`;
