try{const saved=JSON.parse(localStorage.getItem(stateKey)||'null');if(saved&&Array.isArray(saved.drafts))state={...state,...saved,profile:{...state.profile,...saved.profile}}}catch{}
const persist=()=>{try{localStorage.setItem(stateKey,JSON.stringify(state))}catch{notify('This browser could not save the workspace.')}};
const params=()=>new URLSearchParams(location.hash.split('?')[1]||'');
const route=()=>{const path=(location.hash.replace(/^#\/?/,'').split('?')[0]||'home').split('/').map(decodeURIComponent);return path};
const href=(path,values={})=>{const p=new URLSearchParams();for(const [k,v] of Object.entries(values))if(v!==''&&v!==undefined&&v!==null)p.set(k,v);return '#/'+path+(p.size?'?'+p:'')};
